CONTENT = '---\ndocument_type: specification\nspecification_id: CPKS-SPEC-ART\ntitle: Managed Artifact Metadata and Validation Specification\nversion: "0.2"\nstatus: draft\nauthority_scope: vault-wide\nsystem: cpKnowledgeSystem\nowner: Christoph Peters\ncreated: 2026-07-26\nrevised: 2026-07-26\nlanguage: de\ngoverned_by:\n  - CPKS-POL-GOV-AUTH\ndepends_on:\n  - CPKS-DEC-012\n  - CPKS-DEC-015\n  - CPKS-DEC-016\n  - CPKS-DEC-019\n  - CPKS-DEC-020\naligned_with:\n  - CPKS-BL\n  - CPKS-FWK-AIW\nimplements_decisions:\n  - CPKS-DEC-012@1.2\n  - CPKS-DEC-015@1.1\n  - CPKS-DEC-016@1.1\n  - CPKS-DEC-019@1.0\n  - CPKS-DEC-020@1.0\nvalidated_against:\n  - CPKS-POL-GOV-AUTH@1.0\n  - CPKS-BL@0.43\n  - CPKS-FWK-AIW@0.4\n  - CPKS-DEC-020@1.0\n  - CPKS-SPEC-PROC@0.2\nreferences:\n  - CPKS-SPEC-ART@0.1\ncanonical_path: Development/cpKnowledgeSystem/Specifications/CPKS-SPEC-ART@0.2 Managed Artifact Metadata and Validation Specification.md\nsupersedes: []\n---\n\n# CPKS-SPEC-ART – Managed Artifact Metadata and Validation Specification\n\n## 1. Status\n\n**Draft zur fachlichen und technischen Prüfung**\n\nDiese Fassung ist nicht aktiv. Sie überarbeitet den nie aktivierten Draft `CPKS-SPEC-ART@0.1` und ersetzt ihn deshalb nicht im Sinne einer Supersession.\n\nVersion 0.2 verarbeitet insbesondere die Ergebnisse des repräsentativen Validatorlaufs vom 26. Juli 2026:\n\n- unverwaltete Prozessplatzhalter bleiben außerhalb der Prozesskonformitätsprüfung,\n- aktive, historische und Development-Artefakte benötigen unterschiedliche Prüfprofile,\n- abgeschlossene oder zurückgezogene Development-Artefakte dürfen nicht rückwirkend vollständig gegen heutige Regeln geprüft werden,\n- Support-Dokumente benötigen eine prospektive statt pauschal rückwirkende Regelanwendung,\n- `target_artifact` muss auch geplante, noch nicht vorhandene Zielartefakte beschreiben können,\n- zusätzliche Statuswerte werden typabhängig eingeordnet,\n- das Aliasformat für migrierte stabile IDs wird festgelegt,\n- technische Reports und Validatorläufe werden mit `CPKS-DEC-020@1.0` harmonisiert.\n\nDie im Report nachgewiesene parallele aktive Kopie `CPKS-DEC-020@1.0` unter `Decisions/History/` ist ein realer Bestandsfehler. Sie ist kein Spezifikationsproblem und muss separat mechanisch bereinigt werden.\n\nEine Aktivierung erfordert weiterhin:\n\n- Owner Review,\n- Abgleich mit `CPKS-SPEC-PROC@0.2`,\n- erneuten Validatorlauf nach gezielten Bestandskorrekturen,\n- Implementierung der geänderten Prüfprofile,\n- ausdrücklichen Aktivierungsauftrag.\n\n## 2. Zweck\n\nDiese Spezifikation konkretisiert die verbindlichen Governance-Grundsätze für:\n\n- Erkennung verwalteter Artefakte,\n- Dokumenttypen und typabhängige Identitätsfelder,\n- Pflicht- und Bedingungsfelder,\n- stabile und versionsgebundene Referenzen,\n- Impact-Metadaten,\n- ID-, Versions- und Datumsformate,\n- Dateinamen und `canonical_path`,\n- Lifecycle-Zonen,\n- Scanprofile,\n- technische Validierungsregeln,\n- Fehler- und Warnungsklassen,\n- kontrollierte Migration und Aliasbehandlung.\n\nSie ist die technische Grundlage für einen späteren Managed-Artifact-Validator in `cpKnowledgeTools`.\n\n## 3. Geltungsbereich\n\nDiese Spezifikation gilt für verwaltete Artefakte des `cp-wiki`.\n\nEin Dokument ist ein verwaltetes Artefakt, wenn seine Artefaktklasse verbindlich in das Managed-Artifact-Modell aufgenommen wurde und es mindestens besitzt:\n\n```yaml\ndocument_type:\n<type_specific_id>:\ntitle:\nversion:\nstatus:\ncanonical_path:\n```\n\nDiese Spezifikation gilt nicht automatisch für:\n\n- allgemeine Wissensnotizen,\n- importierte Quellen,\n- E-Mails,\n- Medien,\n- einfache Begleitdateien,\n- temporäre Arbeitsnotizen,\n- generierte Ausgaben,\n- andere Dateien ohne eigenständige stabile Identität und Lifecycle-Steuerung.\n\n### 3.1 Prospektive Regelanwendung\n\nNeue Metadaten- und Referenzregeln gelten vollständig für:\n\n- neue verwaltete Artefakte,\n- neue konkrete Fassungen bestehender Artefaktlinien,\n- aktuelle Drafts und Proposals, die nach Inkrafttreten der jeweiligen Regel erstellt oder materiell überarbeitet werden,\n- Support-Dokumente, die ausdrücklich gegen die neue Regel validiert wurden.\n\nHistorische und abgeschlossene Artefakte werden nicht allein wegen später beschlossener Metadatenregeln rückwirkend inkonform.\n\n### 3.2 Bestandsklassen\n\nDer Validator unterscheidet mindestens:\n\n```text\ncurrent_managed\nhistorical_managed\ncurrent_development_managed\nclosed_development_managed\ncurrent_support\nlegacy_support\nunmanaged\n```\n\nDie Klassifikation bestimmt, welche Regeln als Fehler, Warnung oder Information gelten.\n\nEine Datei unter `Processes/` ohne `document_type: process` bleibt `unmanaged`. Ihr Pfad macht sie nicht automatisch zu einem Managed Artifact oder Prozess.\n\n## 4. Normative Begriffe\n\n| Begriff | Bedeutung |\n|---|---|\n| MUSS | verbindliche Konformitätsanforderung |\n| DARF NICHT | verbindliches Verbot |\n| SOLL | Standardanforderung; Abweichung muss begründet sein |\n| SOLL NICHT | grundsätzlich zu vermeidende Ausführung |\n| KANN | zulässige Option |\n\nDie technische Umsetzung darf zusätzliche Diagnoseinformationen erzeugen. Sie darf die normativen Regeln nicht verändern.\n\n## 5. Grundmodell\n\n### 5.1 Maschinenidentität\n\nDie Maschinenidentität eines verwalteten Artefakts ergibt sich mindestens aus:\n\n```text\nzulässiges Scanprofil\n+\ndocument_type\n+\ntypabhängige stabile ID\n+\nversion\n+\nstatus\n```\n\nDateiname, Ablagezone und `canonical_path` sind zusätzliche Konsistenzmerkmale. Sie ersetzen die strukturierte Identität nicht.\n\n### 5.2 Eindeutigkeit\n\n1. Eine stabile Artefakt-ID MUSS vaultweit eindeutig einer Artefaktlinie zugeordnet sein.\n2. Eine Kombination aus stabiler ID und Version DARF höchstens eine kanonische Datei besitzen.\n3. Für eine stabile ID DARF höchstens eine Version den Status `active` besitzen.\n4. Mehrere Dateien DÜRFEN NICHT denselben `canonical_path` beanspruchen.\n5. Eine konkrete historische Version DARF NICHT gleichzeitig im aktiven Bereich und in einem History- oder Archivbereich bestehen.\n\n### 5.3 Kanonische Quelle\n\nDie Markdown-Datei mit gültigem Frontmatter ist die kanonische Quelle für:\n\n- Identität,\n- Version,\n- Status,\n- Titel,\n- tatsächlichen Pfad,\n- ausgehende Beziehungen,\n- Lifecycle-Zuordnung.\n\nGenerierte Indizes sind reproduzierbare, nicht normative Ableitungen.\n\n### 5.4 Profilabhängige Konformität\n\nKonformität wird gegen das für die Datei geltende Prüfprofil bewertet.\n\n```text\naktives oder aktuelles Development-Artefakt\n→ vollständige aktuelle Konformität\n\nhistorisches oder abgeschlossenes Development-Artefakt\n→ Integritäts- und Auflösbarkeitsprofil\n\naktuelles Support-Dokument\n→ beschlossene querschnittliche Support-Regeln\n\nLegacy-Support-Dokument\n→ Lesbarkeit, Provenienz und nicht rückwirkende Diagnose\n\nunverwaltete Datei\n→ Inventarisierung ohne Managed-Artifact-Konformitätsurteil\n```\n\nEine Validatorbeschränkung darf nicht als Vault-Fehler ausgegeben werden. Parser- oder Scope-Grenzen müssen als eigene technische Diagnose kenntlich gemacht werden.\n\n## 6. Kanonische Dokumenttypen und Identitätsfelder\n\n| Artefaktklasse | `document_type` | Identitätsfeld | Typcode |\n|---|---|---|---|\n| Baseline | `baseline` | `baseline_id` | `BL` |\n| Decision Record | `decision_record` | `decision_id` | `DEC` |\n| Policy | `policy` | `policy_id` | `POL` |\n| Framework | `framework` | `framework_id` | `FWK` |\n| Spezifikation | `specification` | `specification_id` | `SPEC` |\n| Prozess | `process` | `process_id` | domänenspezifisches `P` |\n| Work Package | `work_package` | `work_package_id` | `WP` |\n| Normatives Template | `template` | `template_id` | `TPL` |\n| Versioniertes Manual | `manual` | `manual_id` | `MAN` |\n\nEin Artefakt MUSS genau das zu seinem `document_type` gehörende Identitätsfeld führen.\n\nEin zusätzliches allgemeines `artifact_id` ist nicht erforderlich und SOLL NICHT parallel gepflegt werden.\n\n### 6.1 Nicht automatisch verwaltete Support-Typen\n\nFolgende Typen sind nicht allein aufgrund ihres `document_type` eigenständige verwaltete Artefakte:\n\n```text\ndecision_proposal\nchange_proposal\npreflight\nreview\nhandover\nprocess_support\nchecklist\nexample\nreport\nanalysis\nindex\n```\n\nEin Support-Dokument wird nur dann als eigenständig verwaltetes Artefakt behandelt, wenn eine zuständige Decision oder Spezifikation zusätzlich festlegt:\n\n- typabhängiges Identitätsfeld,\n- ID-Schema,\n- Version,\n- Statusmodell,\n- Development- beziehungsweise aktive Ablage,\n- historische Ablage.\n\nUnabhängig davon gelten für `decision_proposal` und `preflight` die Impact-Regeln aus Abschnitt 12.\n\n## 7. Allgemeine Pflichtfelder\n\nJedes **aktuelle** verwaltete Artefakt MUSS mindestens folgende Felder besitzen:\n\n```yaml\ndocument_type:\n<type_specific_id>:\ntitle:\nversion:\nstatus:\nowner:\ncreated:\nrevised:\ncanonical_path:\n```\n\n| Feld | Datentyp | Regel |\n|---|---|---|\n| `document_type` | String | kontrollierter Wert gemäß Abschnitt 6 |\n| typabhängige ID | String | stabile ID gemäß Abschnitt 8 |\n| `title` | String | nicht leer; menschenlesbarer Titel |\n| `version` | String | Format gemäß Abschnitt 9 |\n| `status` | String | zulässiger Wert gemäß Abschnitt 10 |\n| `owner` | String | verantwortlicher Artefakt-Owner |\n| `created` | Datum | ISO-Datum `YYYY-MM-DD` |\n| `revised` | Datum | ISO-Datum `YYYY-MM-DD` |\n| `canonical_path` | String | Vault-relativer tatsächlicher Pfad |\n\nLeere Pflichtfelder sind unzulässig.\n\n### 7.1 Pflichtfelder aktiver Artefakte\n\nEin Artefakt mit `status: active` MUSS zusätzlich besitzen:\n\n```yaml\napproved_by:\napproved_at:\neffective_from:\n```\n\n`approved_at` und `effective_from` verwenden ISO-Daten `YYYY-MM-DD` und dürfen nicht aus Dateizeitstempeln abgeleitet werden.\n\n### 7.2 Bedingte Lifecycle-Felder\n\nEine aktive Nachfolgefassung MUSS die konkret ersetzte Version führen:\n\n```yaml\nsupersedes:\n  - CPKS-POL-GOV-AUTH@0.1\n```\n\nEin nie aktivierter Draft DARF NICHT allein wegen einer neueren Draft-Fassung `superseded` werden.\n\n### 7.3 Historische Pflichtfeldbehandlung\n\nHistorische oder abgeschlossene Development-Artefakte, die vor Einführung dieser Spezifikation entstanden sind, müssen nicht rückwirkend um alle heutigen Pflichtfelder ergänzt werden.\n\nFür sie bleiben mindestens prüfbar:\n\n- lesbares Frontmatter,\n- erkennbare Dokumentklasse,\n- stabile ID, soweit vorhanden,\n- konkrete Version, soweit als Managed Artifact geführt,\n- Status,\n- tatsächlicher `canonical_path`, soweit das Feld vorhanden oder durch eine kontrollierte Migration eingeführt wurde,\n- Eindeutigkeit der Kombination aus stabiler ID und Version.\n\nFehlende heutige Komfort- oder Provenienzfelder werden in diesem Profil als Warnung oder Information behandelt, sofern dadurch keine Identitäts- oder Lifecycle-Mehrdeutigkeit entsteht.\n\n## 8. Stabile IDs\n\n### 8.1 Syntax\n\nEine stabile ID MUSS dem Muster entsprechen:\n\n```regex\n^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+$\n```\n\nSie MUSS:\n\n- mit einem Buchstaben beginnen,\n- ausschließlich Großbuchstaben, Ziffern und Bindestriche enthalten,\n- aus mindestens zwei Segmenten bestehen,\n- vaultweit eindeutig sein,\n- dauerhaft stabil bleiben,\n- ohne Version, Status und Dateiendung geführt werden.\n\nSie DARF NICHT enthalten:\n\n- Leerzeichen,\n- Unterstriche,\n- Umlaute,\n- Schrägstriche,\n- Punkte,\n- Sonderzeichen,\n- Versionsangaben,\n- Statusbegriffe.\n\n### 8.2 Länge\n\nEine neue stabile ID SOLL höchstens 24 Zeichen umfassen und DARF 32 Zeichen nicht überschreiten.\n\nBestehende längere Legacy-IDs werden nicht automatisch umbenannt. Ihre Migration benötigt einen kontrollierten Migrationsfall.\n\n### 8.3 Kontrollierte Codes\n\nMindestens folgende Typcodes sind reserviert:\n\n```text\nBL\nDEC\nPOL\nFWK\nSPEC\nP\nWP\nTPL\nMAN\n```\n\nMindestens folgende Gegenstands- und Domänencodes sind kontrolliert:\n\n```text\nGOV\nAIW\nART\nAUTH\nMETA\nVAL\nPROC\nARCH\nRET\nKM\nMEM\nSRC\nDEV\nOPS\nINT\nVLT\n```\n\nNeue Codes DÜRFEN NICHT pro Datei improvisiert werden.\n\n## 9. Versionen\n\n### 9.1 Datentyp und Syntax\n\n`version` MUSS als YAML-String geführt werden.\n\nZulässig sind zwei oder drei numerische Segmente:\n\n```regex\n^[0-9]+\\.[0-9]+(?:\\.[0-9]+)?$\n```\n\nBeispiele:\n\n```yaml\nversion: "0.1"\nversion: "0.42"\nversion: "1.0"\nversion: "1.2.1"\n```\n\nNicht zulässig:\n\n```yaml\nversion: 1.0\nversion: v1.0\nversion: "1"\nversion: "1.0-draft"\n```\n\nDer Lifecycle-Status ist kein Bestandteil der Version.\n\n### 9.2 Vergleich\n\nVersionssegmente werden numerisch verglichen.\n\n```text\n0.9 < 0.10\n1.2 < 1.10\n1.2 < 1.2.1\n```\n\nDiese Spezifikation schreibt keine semantische Bedeutung einzelner Versionssprünge vor.\n\n## 10. Statusmodell\n\n### 10.1 Gemeinsamer Statuskern\n\nDer dokumenttypübergreifende Statuskern lautet:\n\n```text\ndraft\nproposed\nactive\nsuperseded\ndeprecated\narchived\n```\n\n| Status | Bedeutung |\n|---|---|\n| `draft` | Fassung wird bearbeitet und ist nicht verbindlich |\n| `proposed` | Fassung liegt zur Freigabe vor und ist nicht verbindlich |\n| `active` | Fassung ist ausdrücklich freigegeben und verbindlich |\n| `superseded` | zuvor aktive Fassung wurde durch einen aktiven Nachfolger ersetzt |\n| `deprecated` | Fassung soll nicht mehr für neue Arbeit verwendet werden |\n| `archived` | Fassung wird ausschließlich historisch oder auditbezogen aufbewahrt |\n\n### 10.2 Typabhängige zusätzliche Statuswerte\n\nZusätzliche Statuswerte sind nur in einem ausdrücklich definierten Typ- oder Profilkontext zulässig.\n\n#### `withdrawn`\n\n`withdrawn` ist zulässig für nie aktivierte Fassungen verwalteter Artefakte und für Proposals, wenn der Owner sie vor einer Aktivierung oder Annahme zurückzieht.\n\nEin `withdrawn` Artefakt:\n\n- war nie verbindlich,\n- darf nicht `superseded` sein,\n- gehört zum abgeschlossenen Development-Lifecycle,\n- wird nicht gegen alle aktuellen Development-Regeln rückwirkend geprüft.\n\n#### `rejected`\n\n`rejected` ist zulässig für Proposal-, Review- und Intake-Artefakte, wenn eine zuständige Entscheidung die vorgeschlagene Änderung ausdrücklich ablehnt.\n\n`rejected` ist kein allgemeiner Status einer zuvor aktiven normativen Fassung.\n\n#### `completed`\n\n`completed` ist zulässig für `work_package` und ausdrücklich definierte operative Ausführungsartefakte, deren Abschlusskriterien erfüllt wurden.\n\n#### `cancelled`\n\n`cancelled` ist zulässig für `work_package`, geplante Aktivitäten und ausführungsbezogene Change-Artefakte, die ohne vollständige Umsetzung beendet wurden.\n\n### 10.3 Unzulässige Verwendung von `identified`\n\n`identified` ist kein Lifecycle-Status eines Managed Artifacts.\n\nEin identifizierter Bedarf, Prozessgegenstand, Impact-Kandidat oder möglicher Change wird in einem dafür geeigneten Feld oder Support-Artefakt dokumentiert, beispielsweise:\n\n```yaml\nprocessing_state: identified\ncandidate_status: identified\n```\n\nEr wird dadurch nicht zu einer formalen Managed-Artifact-Fassung.\n\n### 10.4 Typ-Profil\n\nEin Validator MUSS den Status gegen `document_type` und Prüfprofil bewerten.\n\nEin typabhängiger Status außerhalb seines zulässigen Kontexts erzeugt:\n\n```text\ninvalid_status_for_document_type\n```\n\nEin Legacy-Artefakt mit früher verwendeter Statussemantik kann als Warnung oder Information behandelt werden, sofern keine aktive Mehrdeutigkeit entsteht.\n\n## 11. Governance-Referenzen\n\n### 11.1 Stabile Beziehungsfelder\n\nFolgende Felder verwenden ausschließlich stabile IDs ohne Version:\n\n```yaml\ngoverned_by:\ndepends_on:\naligned_with:\nrelated_decisions:\n```\n\nSie sind Listen von Strings.\n\n### 11.2 Versionsgebundene Nachweisfelder\n\nFolgende Felder verwenden ausschließlich konkrete Versionsreferenzen:\n\n```yaml\nimplements_decisions:\nvalidated_against:\nsupersedes:\n```\n\nFormat:\n\n```regex\n^[A-Z][A-Z0-9]*(?:-[A-Z0-9]+)+@[0-9]+\\.[0-9]+(?:\\.[0-9]+)?$\n```\n\n### 11.3 Gemischtes Feld `references`\n\n`references` darf stabile oder versionsgebundene Artefaktreferenzen enthalten.\n\n`references` erzeugt allein keine normative Abhängigkeit, keinen Implementierungsnachweis und keinen Validierungsnachweis.\n\n### 11.4 `source_artifact`\n\n`source_artifact` bezeichnet eine bereits vorhandene konkrete Ausgangsfassung und verwendet eine skalare versionsgebundene Referenz:\n\n```yaml\nsource_artifact: CPKS-SPEC-ART@0.1\n```\n\n### 11.5 `target_artifact`\n\n`target_artifact` darf entweder eine bereits vorhandene konkrete Fassung oder ein geplantes Zielartefakt bezeichnen.\n\nBereits vorhandenes Ziel:\n\n```yaml\ntarget_artifact: CPKS-SPEC-ART@0.2\n```\n\nGeplantes oder noch nicht vorhandenes Ziel:\n\n```yaml\ntarget_artifact:\n  reference: CPKS-SPEC-ART@0.2\n  document_type: specification\n  target_status: draft\n  proposed_canonical_path: Development/cpKnowledgeSystem/Specifications/CPKS-SPEC-ART@0.2 Managed Artifact Metadata and Validation Specification.md\n```\n\nFür den strukturierten Descriptor gilt:\n\n- `reference` ist verpflichtend und versionsgebunden,\n- `document_type` ist optional, aber bei neuen Artefaktlinien empfohlen,\n- `target_status` ist optional,\n- `proposed_canonical_path` ist optional und muss bei Angabe Vault-relativ sein,\n- der Descriptor erzeugt noch kein tatsächlich vorhandenes Ziel,\n- die Auflösung darf bei einem geplanten Ziel als `planned_target_not_materialized` und nicht als allgemeiner Referenzfehler berichtet werden.\n\nFrühere strukturierte Zielbeschreibungen ohne `reference` gelten als Legacy-Form. Sie werden nicht als leerer String behandelt, sondern als Warnung zur kontrollierten Migration ausgegeben.\n\n### 11.6 Keine manuellen Rückwärtsbeziehungen\n\nFelder wie:\n\n```yaml\ngoverns:\nreferenced_by:\ndepended_on_by:\nimplemented_by:\n```\n\nDÜRFEN NICHT als manuell gepflegte Gegenlisten erzeugt werden.\n\n## 12. Impact-Metadaten\n\n### 12.1 Anwendungsbereich\n\nNeue oder materiell überarbeitete Governance-Change-Artefakte der folgenden Typen MÜSSEN `affected_artifacts` führen:\n\n```text\ndecision_proposal\npreflight\nwork_package\n```\n\nDie Pflicht gilt prospektiv ab der für den Artefaktkontext maßgeblichen aktiven Impact-Regel.\n\n### 12.2 Datentyp und Referenzform\n\n`affected_artifacts` ist eine Liste stabiler Artefakt-IDs ohne Version.\n\nZulässig:\n\n```yaml\naffected_artifacts:\n  - CPKS-POL-GOV-AUTH\n  - CPKS-SPEC-ART\n  - GOV-P01\n```\n\nNicht zulässig:\n\n```yaml\naffected_artifacts:\n  - CPKS-POL-GOV-AUTH@1.0\n```\n\n### 12.3 Semantik\n\nEin Eintrag bezeichnet einen bekannten Impact-Kandidaten. Er bedeutet keine konkrete Prüfung, beschlossene Änderung, dauerhafte Abhängigkeit oder bestätigte Revalidierung.\n\nEine leere Liste ist zulässig:\n\n```yaml\naffected_artifacts: []\n```\n\nSie dokumentiert nur den aktuellen Erfassungsstand.\n\nAktive normative Artefakte DÜRFEN `affected_artifacts` nicht als dauerhaftes Beziehungsfeld führen.\n\n### 12.4 Legacy-Change-Artefakte\n\nEin Change- oder Support-Artefakt, das vor der maßgeblichen Impact-Regel erstellt und seitdem nicht materiell überarbeitet wurde, wird nicht rückwirkend als fehlerhaft behandelt.\n\nEs erzeugt höchstens:\n\n```text\nlegacy_impact_metadata\n```\n\nals Warnung oder Information.\n\nEin bewusst migriertes oder revalidiertes Legacy-Artefakt muss danach die aktuelle Referenzform vollständig erfüllen.\n\n## 13. Dateinamen\n\n### 13.1 Aktive Fassungen\n\n```text\n<stable_artifact_id> <normalized_title>.md\n```\n\nVersion und Status DÜRFEN im aktiven Dateinamen nicht vorkommen.\n\n### 13.2 Nicht aktive konkrete Fassungen\n\n```text\n<stable_artifact_id>@<version> <normalized_title>.md\n```\n\nDer ausgeschriebene Status DARF nicht zusätzlich im Dateinamen stehen.\n\n### 13.3 Titel-Normalisierung\n\nFür den Dateinamen wird `title` wie folgt normalisiert:\n\n1. Unicode wird in NFC normalisiert.\n2. Führende und nachfolgende Leerzeichen werden entfernt.\n3. Die Zeichen `< > : " / \\ | ? *` und Steuerzeichen werden durch einen Bindestrich mit umgebenden Leerzeichen ersetzt.\n4. Mehrfache Leerzeichen werden zu einem Leerzeichen zusammengeführt.\n5. Mehrfache unmittelbar aufeinanderfolgende Bindestriche werden zu einem Bindestrich zusammengeführt.\n6. Nachfolgende Punkte und Leerzeichen werden entfernt.\n7. Umlaute und andere gültige Unicode-Buchstaben bleiben erhalten.\n\n## 14. `canonical_path`\n\n`canonical_path` MUSS:\n\n- als Vault-relativer POSIX-Pfad geführt werden,\n- mit dem tatsächlichen gegenwärtigen Pfad übereinstimmen,\n- den tatsächlichen Dateinamen enthalten,\n- ohne führenden Schrägstrich geschrieben werden,\n- die Dateiendung `.md` enthalten.\n\nAbsolute lokale Dateisystempfade und frühere Pfade nach einer Verschiebung sind unzulässig.\n\n## 15. Lifecycle-Zonen\n\n### 15.1 Aktive Zone\n\nEin Artefakt mit `status: active` MUSS im typabhängigen aktiven kanonischen Bereich liegen.\n\n### 15.2 Aktuelle Development-Zone\n\nAktuelle nicht aktivierte Fassungen mit `draft` oder `proposed` liegen im zuständigen Development-Kontext und verwenden einen versionierten Dateinamen.\n\n### 15.3 Abgeschlossener Development-Lifecycle\n\nNie aktivierte Fassungen mit `withdrawn` sowie typabhängig `rejected`, `completed` oder `cancelled` gehören zum abgeschlossenen Development-Lifecycle.\n\nKanonische Zielbereiche sind vorzugsweise lokale `History/`- oder `Archive/`-Bereiche des zuständigen Development-Kontexts.\n\nBestehende abgeschlossene Artefakte außerhalb eines solchen Unterbereichs dürfen bis zu einer kontrollierten Migration an ihrem nachgewiesenen Pfad verbleiben. Dies erzeugt höchstens eine Platzierungswarnung, sofern keine aktive oder konkrete Versionskollision entsteht.\n\n### 15.4 Decision History\n\nNicht aktive konkrete Decision-Fassungen liegen unter:\n\n```text\nSystems/cpKnowledgeSystem/Governance/Decisions/History/\n```\n\nDer Speicherort ändert den Status nicht.\n\nEine aktive Decision darf dort nicht liegen. Eine identische aktive Kopie in `Decisions/` und `Decisions/History/` ist ein blockierender Duplicate- und Lifecycle-Fehler.\n\n### 15.5 Lokale Archive\n\nAndere historische Managed Artifacts folgen dem local-first Modell.\n\nBeispiele:\n\n```text\nSystems/cpKnowledgeSystem/Governance/Archive/Baselines/\nSystems/cpKnowledgeSystem/Governance/Archive/Frameworks/\nSystems/cpKnowledgeSystem/Governance/Archive/Policies/\nSystems/cpKnowledgeSystem/Governance/Archive/Specifications/\nProcesses/<Domain>/Archive/\n```\n\n### 15.6 Zentrales Archiv\n\nDas Top-Level-Verzeichnis `Archive/` wird nicht als Standardziel für historische Managed Artifacts mit bestehendem fachlichen Parent-Kontext verwendet.\n\n## 16. Scan- und Prüfprofile\n\n### 16.1 `active_governance`\n\nMindestbereiche:\n\n```text\nSystems/cpKnowledgeSystem/Governance/**/*.md\nProcesses/Governance/**/*.md\n```\n\nAusgeschlossen:\n\n```text\n**/Archive/**\n**/History/**\n```\n\nNur Dateien mit einem im Profil verwalteten `document_type` werden vollständig geprüft.\n\n### 16.2 `governance_change_current`\n\nMindestbereiche:\n\n```text\nDevelopment/cpKnowledgeSystem/Governance/**/*.md\nDevelopment/cpKnowledgeSystem/Specifications/**/*.md\nDevelopment/cpKnowledgeSystem/Work Packages/**/*.md\n```\n\nVollständig geprüft werden:\n\n- Managed Artifacts mit `draft` oder `proposed`,\n- aktuelle Support-Dokumente,\n- ausdrücklich gegen die aktuelle Regelbasis revalidierte Artefakte.\n\n### 16.3 `governance_change_closed`\n\nDieses Profil umfasst abgeschlossene Development-Artefakte mit:\n\n```text\nwithdrawn\nrejected\ncompleted\ncancelled\n```\n\nsowie Dateien in lokalen Development-`History/`- oder `Archive/`-Bereichen.\n\nGeprüft werden insbesondere:\n\n- YAML-Lesbarkeit,\n- Identität und Version,\n- Duplicate-Versionen,\n- aktive Statuswerte in geschlossenen Zonen,\n- tatsächlicher `canonical_path`,\n- versionsgebundene Auflösbarkeit, soweit erforderlich,\n- Erhaltung der Provenienz.\n\nHeutige Referenzformen, Pflichtfelder und Impact-Metadaten werden nicht pauschal rückwirkend als Fehler angewendet.\n\n### 16.4 `governance_history`\n\nMindestbereiche:\n\n```text\nSystems/cpKnowledgeSystem/Governance/Archive/**/*.md\nSystems/cpKnowledgeSystem/Governance/Decisions/History/**/*.md\n```\n\nDas Profil prüft Integrität und Auflösbarkeit, nicht vollständige rückwirkende Konformität zu jeder späteren Regel.\n\n### 16.5 `legacy_support`\n\nSupport-Dokumente, deren Regelstand nicht eindeutig als aktuell nachgewiesen ist, werden mit einem eingeschränkten Profil geprüft.\n\nParserfehler, aktive Duplikate und eindeutige Pfadkollisionen bleiben Fehler. Später eingeführte Referenz- und Impact-Regeln erzeugen Warnungen oder Informationen.\n\n### 16.6 `complete_governance_lifecycle`\n\nDieses Profil vereinigt:\n\n```text\nactive_governance\ngovernance_change_current\ngovernance_change_closed\ngovernance_history\nlegacy_support\n```\n\nEs wird für versionsgebundene Referenzauflösung, Supersession-Ketten, Audit, Provenienz und lifecycle-weite Duplikatprüfung benötigt.\n\n### 16.7 Weitere Scanprofile\n\nWeitere Komponenten- oder vaultweite Profile müssen ausdrücklich konfiguriert werden.\n\nEin Validator DARF NICHT jede Markdown-Datei im Vault allein aufgrund vorhandener YAML-Felder automatisch als Managed Artifact behandeln.\n\nUnverwaltete Dateien unter `Processes/` bleiben Inventar und werden nur durch `document_type: process` zu Prozesskandidaten.\n\n## 17. Validierungsmodell\n\n### 17.1 Ergebnisstufen\n\n```text\nerror\nwarning\ninfo\n```\n\n| Stufe | Bedeutung |\n|---|---|\n| `error` | Konformität im geltenden Profil nicht gegeben; Aktivierung oder Gesamtvalidierung blockiert |\n| `warning` | potenzielle Inkonsistenz, Migration oder Review erforderlich |\n| `info` | nicht blockierende Diagnose, Bestands- oder Migrationshinweis |\n\n### 17.2 Profilabhängige Severity\n\nDasselbe Merkmal kann abhängig vom Prüfprofil unterschiedlich bewertet werden.\n\nBeispiele:\n\n| Befund | aktuelles Artefakt | historisches oder geschlossenes Artefakt |\n|---|---|---|\n| fehlendes aktuelles Pflichtfeld | Fehler | Warnung oder Information |\n| alte stabile ID | Fehler oder Warnung | Information |\n| alte Referenzform | Fehler | Warnung oder Information |\n| ungültiges YAML | Fehler | Fehler |\n| doppelte ID und Version | Fehler | Fehler |\n| aktive Kopie in History | Fehler | Fehler |\n| falscher `canonical_path` | Fehler | Fehler, sofern Feld vorhanden |\n| fehlendes `affected_artifacts` | Fehler bei aktueller Pflicht | Warnung oder Information |\n\n### 17.3 Mindestfehlerklassen\n\n```text\ninvalid_yaml_frontmatter\nmissing_required_field\nempty_required_field\nunknown_document_type\nidentity_field_mismatch\nmissing_identity_field\ninvalid_artifact_id\nartifact_id_too_long\nduplicate_stable_id_and_version\nduplicate_active_artifact\nmultiple_active_versions\ninvalid_version\ninvalid_status\ninvalid_status_for_document_type\nmissing_approval_metadata\ninvalid_date\nrevised_before_created\nartifact_id_filename_mismatch\ntitle_filename_mismatch\nactive_filename_mismatch\nversioned_filename_mismatch\nstatus_in_filename\ncanonical_path_mismatch\nduplicate_canonical_path\nactive_artifact_in_change_zone\nactive_artifact_in_history_or_archive\ninactive_artifact_in_active_zone\ndraft_or_proposed_in_active_zone\ninvalid_reference_form\ninvalid_target_artifact_descriptor\nno_active_reference_target\nmultiple_active_reference_targets\nunresolved_versioned_reference\ninvalid_affected_artifact_reference\naffected_artifacts_on_active_normative_artifact\nunresolved_supersedes_reference\nparallel_canonical_version\n```\n\n### 17.4 Mindestwarnungen\n\n```text\nunused_optional_field\nempty_optional_list\nlegacy_artifact_id\nlegacy_document_type\nlegacy_reference_form\nlegacy_impact_metadata\nclosed_development_artifact_outside_history\nreference_to_newer_active_version_available\nvalidated_against_not_current\ntitle_normalization_changed\nunmanaged_support_artifact_with_independent_identity\nunknown_controlled_abbreviation\nplanned_target_not_materialized\n```\n\n`validated_against_not_current` ist eine Warnung und kein Fehler, wenn die angegebene konkrete Version existiert.\n\n### 17.5 Validator-Diagnosen\n\nTechnische Einschränkungen des Validators werden nicht als Artefaktfehler ausgegeben.\n\nMindestens folgende technische Diagnosen müssen getrennt werden können:\n\n```text\nvalidator_parser_limitation\nscan_scope_incomplete\nunsupported_yaml_construct\nreference_target_outside_scan\n```\n\n### 17.6 Fehlerobjekt\n\nEine maschinenlesbare Diagnose SOLL mindestens enthalten:\n\n```yaml\nseverity:\ncode:\nmessage:\npath:\nline:\nfield:\nartifact_id:\nversion:\nprofile:\nactual:\nexpected:\nrule_source:\n```\n\nNicht anwendbare Felder können entfallen.\n\n### 17.7 Reportablage\n\nTechnische Validatorläufe und vollständige Laufdiagnosen folgen `CPKS-DEC-020@1.0`.\n\nDer Standardbereich für technische Validierungsläufe ist:\n\n```text\n/Users/cp/Library/Application Support/cpKnowledgeTools/Runs/cp-wiki/validation/\n```\n\nEin dauerhaft menschenrelevanter, reproduzierbarer Bericht kann zusätzlich kontrolliert unter:\n\n```text\nGenerated/Validation/\n```\n\nübernommen werden.\n\nDer Backup-Bereich darf nicht als Standardziel für Validatorreports verwendet werden.\n\n## 18. Referenzauflösung\n\n### 18.1 Stabile Referenzen\n\nEine stabile Referenz wird im aktiven Profil auf genau eine aktive Fassung aufgelöst.\n\n```text\nkein aktives Ziel\n→ no_active_reference_target\n\nmehrere aktive Ziele\n→ multiple_active_reference_targets\n```\n\nEine stabile Referenz DARF NICHT stillschweigend auf eine historische oder nur vorgeschlagene Fassung aufgelöst werden.\n\n### 18.2 Versionsgebundene Referenzen\n\nEine versionsgebundene Referenz wird im vollständigen Lifecycle-Profil auf genau die genannte Kombination aus stabiler ID und Version aufgelöst.\n\nDas Ziel darf insbesondere `active`, `superseded`, `deprecated`, `archived` oder `withdrawn` sein.\n\n### 18.3 Geplante Zielartefakte\n\nEine `target_artifact.reference` darf auf eine noch nicht materialisierte geplante Version verweisen.\n\nDies erzeugt:\n\n```text\nplanned_target_not_materialized\n```\n\nals Warnung oder Information, solange der Descriptor syntaktisch gültig ist und der Change-Kontext ein geplantes Ziel erlaubt.\n\n### 18.4 Aliasauflösung\n\nVor der Meldung einer nicht auflösbaren stabilen oder versionsgebundenen Referenz wird die kontrollierte Aliasabbildung aus Abschnitt 19 geprüft.\n\nDie Aliasauflösung ändert die gespeicherte historische Referenz nicht. Sie liefert lediglich eine kanonische Auflösung und eine Migrationsdiagnose.\n\nMehrere aktuelle Artefaktlinien dürfen nicht dieselbe frühere ID beanspruchen.\n\n## 19. Kontrollierte Migration und Aliasbehandlung\n\n### 19.1 Historische Erhaltung\n\nAlte IDs dürfen in historischen Artefakten, ausdrücklich dokumentierten Migrationstabellen, historischen Beispielen sowie Provenienz- und Auditnachweisen erhalten bleiben.\n\n### 19.2 Aktive Verwendung\n\nEine alte ID DARF nach abgeschlossener Migration nicht als aktive stabile Identität oder aktive Beziehungsreferenz fortgeführt werden.\n\n### 19.3 Kanonisches Aliasformat\n\nDas aktuelle kanonische Artefakt einer migrierten Artefaktlinie darf folgendes Feld führen:\n\n```yaml\nformer_ids:\n  - CPKS-POL-GOVERNANCE-AUTHORING\n```\n\nFür `former_ids` gilt:\n\n- Liste stabiler IDs ohne Version,\n- keine Duplikate,\n- keine aktuelle eigene ID,\n- keine Status- oder Dateinamenwerte,\n- vaultweit eindeutige Zuordnung zu genau einer aktuellen Artefaktlinie,\n- nur für tatsächlich verwendete frühere stabile IDs,\n- keine Pflicht zur rückwirkenden Ergänzung jeder historischen Datei.\n\nEin zentrales manuell gepflegtes Aliasregister wird nicht geführt.\n\nValidatoren und Generatoren dürfen aus den verteilten `former_ids` reproduzierbar eine Alias-Sicht ableiten.\n\n### 19.4 Versionsauflösung über Aliase\n\nEine historische Referenz:\n\n```text\nCPKS-POL-GOVERNANCE-AUTHORING@0.1\n```\n\ndarf über:\n\n```yaml\nformer_ids:\n  - CPKS-POL-GOVERNANCE-AUTHORING\n```\n\nauf die Artefaktlinie `CPKS-POL-GOV-AUTH` und anschließend auf deren konkrete Version `0.1` aufgelöst werden.\n\nDie Auflösung darf nicht:\n\n- eine zweite aktive Identität erzeugen,\n- eine nicht vorhandene Version erfinden,\n- eine unklare Referenz stillschweigend umdeuten,\n- historische Dateien automatisch überschreiben.\n\n### 19.5 Aliasfehler\n\nMindestens folgende Fehlerklassen gelten:\n\n```text\nformer_id_equals_current_id\nduplicate_former_id\nformer_id_claimed_by_multiple_artifacts\ninvalid_former_id\nalias_version_target_missing\n```\n\nHistorische Verwendung einer auflösbaren früheren ID ist im historischen Profil eine Information, kein Fehler.\n\n## 20. Konformitätsregel\n\nEin aktuelles verwaltetes Artefakt ist konform, wenn:\n\n1. es in einem zulässigen Scanprofil liegt,\n2. `document_type` und typabhängiges Identitätsfeld übereinstimmen,\n3. alle im Profil verpflichtenden Felder vorhanden und gültig sind,\n4. ID, Version und Status zulässige Werte besitzen,\n5. Dateiname und `canonical_path` dem tatsächlichen Zustand entsprechen,\n6. Lifecycle-Zone und Status kompatibel sind,\n7. stabile und versionsgebundene Referenzen korrekt verwendet werden,\n8. alle erforderlichen Referenzen oder geplanten Target-Descriptoren auflösbar beziehungsweise gültig sind,\n9. keine konkurrierende aktive oder konkrete Version existiert,\n10. die Validierung im geltenden Profil keine Fehler erzeugt.\n\nEin historisches oder abgeschlossenes Development-Artefakt ist im eingeschränkten Profil konform, wenn seine Identität, Provenienz, Lesbarkeit, Pfadzuordnung und lifecycle-weite Eindeutigkeit erhalten bleiben.\n\nEine erfolgreiche technische Validierung ersetzt nicht Owner Review, normative Autoritätsprüfung, Scope-Prüfung oder ausdrückliche Aktivierungsbefugnis.\n\n## 21. Nicht Bestandteil dieser Spezifikation\n\nDiese Spezifikation definiert nicht:\n\n- fachliche Inhalte einzelner Governance-Artefakte,\n- den vollständigen Aufbau einer Prozessbeschreibung,\n- die vollständigen Arbeitsschritte von `GOV-P01`,\n- die konkrete Python-Paketarchitektur des Validators,\n- eine verpflichtende Datenbank,\n- einen verpflichtenden persistenten Index,\n- die UI eines Review- oder Intake-Werkzeugs,\n- automatische Reparaturen ohne Review,\n- die vollständige Aufnahme aller Vault-Dokumentklassen in das Managed-Artifact-Modell.\n\n## 22. Aktivierungsblocker und Owner Review\n\nVor Aktivierung müssen mindestens entschieden oder nachgewiesen werden:\n\n1. Entfernung der parallelen aktiven Kopie `CPKS-DEC-020@1.0` aus `Decisions/History/`,\n2. Implementierung der getrennten Prüfprofile im Validator,\n3. Unterstützung von `former_ids` und Aliasauflösung,\n4. Unterstützung des strukturierten `target_artifact`-Descriptors,\n5. Abgleich des Statusmodells mit `CPKS-SPEC-PROC@0.2`,\n6. erneuter Test gegen aktive, historische, aktuelle Development- und geschlossene Development-Artefakte,\n7. Prüfung der Dateinamen-Normalisierung auf macOS, Git und Obsidian,\n8. kontrollierte Behandlung der archivierten Vault-Spezifikationen 1.0 und 1.1,\n9. Owner Review des vollständigen Drafts,\n10. ausdrücklicher Aktivierungsauftrag.\n\nNicht erforderlich für die Aktivierung ist eine rückwirkende Vollmigration jedes alten Preflights oder zurückgezogenen Drafts. Deren Integrität und Provenienz müssen jedoch erhalten bleiben.\n\n## 23. Kurzregel\n\n> Ein Managed Artifact wird durch strukturierten Dokumenttyp, typabhängige stabile ID, Version, Status und zulässiges Prüfprofil identifiziert. Aktive und aktuelle Development-Artefakte müssen das aktuelle Schema vollständig erfüllen; historische, abgeschlossene Development- und Legacy-Support-Artefakte werden mit einem eingeschränkten Integritätsprofil geprüft. Dauerhafte Beziehungen verwenden stabile IDs, konkrete Nachweise unveränderliche Versionen. Frühere stabile IDs werden verteilt über `former_ids` aufgelöst. Geplante Zielartefakte dürfen über einen strukturierten `target_artifact`-Descriptor beschrieben werden. Ein Validator darf Inkonsistenzen erkennen, aber weder historische Provenienz überschreiben noch normative Entscheidungen ergänzen oder Artefakte ohne Autorisierung reparieren und aktivieren.\n'


class PlacementError(RuntimeError):
    pass


def assert_canonical_script_location() -> None:
    actual = Path(__file__).resolve()
    expected = CANONICAL_SCRIPT.resolve()
    if actual != expected:
        raise PlacementError(
            "Script is not in its canonical repository location.\n"
            f"Expected: {expected}\n"
            f"Actual:   {actual}"
        )


def split_frontmatter(text: str) -> str:
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        raise PlacementError("Missing YAML frontmatter.")
    for index in range(1, len(lines)):
        if lines[index].strip() == "---":
            return "\n".join(lines[1:index])
    raise PlacementError("Unclosed YAML frontmatter.")


def scalar(frontmatter: str, field: str) -> str | None:
    match = re.search(
        rf"(?m)^{re.escape(field)}:\s*[\"']?([^\n\"']+)[\"']?\s*$",
        frontmatter,
    )
    return match.group(1).strip() if match else None


def validate(text: str) -> None:
    fm = split_frontmatter(text)
    expected = {
        "document_type": "specification",
        "specification_id": "CPKS-SPEC-ART",
        "version": "0.2",
        "status": "draft",
        "canonical_path": TARGET_REL.as_posix(),
    }
    for field, wanted in expected.items():
        actual = scalar(fm, field)
        if actual != wanted:
            raise PlacementError(
                f"{field} expected {wanted!r}, got {actual!r}"
            )

    for field in ("approved_by", "approved_at", "effective_from"):
        if scalar(fm, field) is not None:
            raise PlacementError(f"Draft must not contain {field}.")


def atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp_name = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".placement.tmp",
        dir=path.parent,
    )
    temp_path = Path(temp_name)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp_path, 0o644)
        os.replace(temp_path, path)
    finally:
        temp_path.unlink(missing_ok=True)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()

    assert_canonical_script_location()
    validate(CONTENT)

    target = VAULT / TARGET_REL
    timestamp = dt.datetime.now().astimezone().strftime("%Y%m%dT%H%M%S%z")
    mode = "apply" if args.apply else "dry-run"
    run_dir = (
        RUN_ROOT
        / f"{timestamp}-place-CPKS-SPEC-ART-0.2-{mode}"
    )
    run_dir.mkdir(parents=True, exist_ok=False)

    if target.exists():
        existing = target.read_text(encoding="utf-8")
        validate(existing)
        if existing != CONTENT:
            raise PlacementError(
                "Target exists with different content. No overwrite performed."
            )
        state = "already_present"
    else:
        state = "planned"

    report = {
        "mode": mode,
        "state": state,
        "artifact": "CPKS-SPEC-ART@0.2",
        "status": "draft",
        "target": TARGET_REL.as_posix(),
        "sha256": hashlib.sha256(CONTENT.encode("utf-8")).hexdigest(),
        "previous_draft_modified": False,
        "activation_performed": False,
        "commit_created": False,
        "push_performed": False,
    }
    (run_dir / "placement-report.json").write_text(
        json.dumps(report, indent=2, ensure_ascii=False) + "\n",
        encoding="utf-8",
    )
    (run_dir / TARGET_REL.name).write_text(CONTENT, encoding="utf-8")

    if not args.apply:
        print("Dry run completed. No Vault files were changed.")
        print(f"Target: {TARGET_REL}")
        print(f"Run report: {run_dir}")
        return 0

    if not target.exists():
        atomic_write(target, CONTENT)

    validate(target.read_text(encoding="utf-8"))
    print("CPKS-SPEC-ART@0.2 placed and validated as draft.")
    print(f"Target: {target}")
    print(f"Run report: {run_dir}")
    print("CPKS-SPEC-ART@0.1 was not changed.")
    print("No activation, Git commit or push was performed.")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except PlacementError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(2)
